    }
}

class Sensor {
    public int sampleRate = 10;
}

class HighPrecisionSensor extends Sensor {
    public int sampleRate = 100;

    public void printBothRates() {
        System.out.println("Subclass rate: " + sampleRate);
        System.out.println("Superclass rate: " + super.sampleRate);
    }
}

public class SensorApp {
    public static void main(String[] args) {
        HighPrecisionSensor s = new HighPrecisionSensor();
        s.printBothRates();

        Sensor baseRef = s;
        System.out.println("Access through base reference: " + baseRef.sampleRate);
        System.out.println("Access through cast reference: " + ((HighPrecisionSensor) baseRef).sampleRate);
    }
}

class Account {
    private String accountType;
    public Account(String accountType) {
        this.accountType = accountType;
    }
    public String getAccountType() { return accountType; }
}

class VIPAccount extends Account {
    public VIPAccount() {
        super("VIP");
    }
}

class StandardAccount extends Account {
    public StandardAccount() {
        super("Standard");
    }
}

public class CleanAccountApp {
    public static void main(String[] args) {
        Account[] accounts = new Account[] {
            new VIPAccount(),
            new StandardAccount()
        };
        for (Account acc : accounts) {
            System.out.println("Account Type: " + acc.getAccountType());
        }
    }
}

